import org.apache.batik.transcoder.image.PNGTranscoder import org.apache.batik.transcoder.TranscoderInput import org.apache.batik.transcoder.TranscoderOutput
def kotlinSvgDir = new File(project.basedir, '../submodules/IntellijCommunity/plugins/kotlin/base/resources/resources/org/jetbrains/kotlin/idea/icons') def platformSvgDir = new File(project.basedir, '../submodules/IntellijCommunity/platform/icons/src/nodes') def outDir = new File(project.build.outputDirectory, 'io/github/nbplugins/kotlin/nbm/icons') outDir.mkdirs()
// svgDir -> output name def icons = [ [kotlinSvgDir, 'field_value.svg' , 'val.png'], [kotlinSvgDir, 'field_variable.svg' , 'var.png'], [kotlinSvgDir, 'abstract_extension_function.svg', 'extension_function.png'], [kotlinSvgDir, 'classKotlin.svg' , 'class_kotlin.png'], [kotlinSvgDir, 'abstractClassKotlin.svg' , 'abstract_class.png'], [kotlinSvgDir, 'interfaceKotlin.svg' , 'interface.png'], [kotlinSvgDir, 'enumKotlin.svg' , 'enum.png'], [kotlinSvgDir, 'annotationKotlin.svg' , 'annotation.png'], [kotlinSvgDir, 'objectKotlin.svg' , 'object.png'], [kotlinSvgDir, 'classInitializerKotlin.svg' , 'class_initializer.png'], [kotlinSvgDir, 'lambda.svg' , 'lambda.png'], [kotlinSvgDir, 'suspendCall.svg' , 'suspend_function.png'], [kotlinSvgDir, 'typeAlias.svg' , 'type_alias.png'], [kotlinSvgDir, 'value.svg' , 'value_class.png'], [kotlinSvgDir, 'actual.svg' , 'actual.png'], [kotlinSvgDir, 'expect.svg' , 'expect.png'], [kotlinSvgDir, 'kotlin_file.svg' , 'kotlin_file.png'], [kotlinSvgDir, 'kotlin.svg' , 'kotlin.png'], // Platform icons (platform/icons/src/nodes/, Apache 2.0) [platformSvgDir, 'function.svg' , 'function.png'], [platformSvgDir, 'method.svg' , 'method.png'], [platformSvgDir, 'variable.svg' , 'variable.png'], [platformSvgDir, 'parameter.svg' , 'parameter.png'], ]
icons.each { entry -> def (svgDir, svgName, pngName) = entry def svgFile = new File(svgDir, svgName) if (!svgFile.exists()) { log.warn("SVG not found: ${svgFile.absolutePath}") return } def t = new PNGTranscoder() t.addTranscodingHint(PNGTranscoder.KEY_WIDTH, 16f) t.addTranscodingHint(PNGTranscoder.KEY_HEIGHT, 16f) def os = new FileOutputStream(new File(outDir, pngName)) t.transcode(new TranscoderInput(svgFile.toURI().toString()), new TranscoderOutput(os)) os.close() log.info("Generated ${pngName} (16px)") }
